module top_module (
    input CLK,
    input SHIFT,
    input [3:0] in_0,
    input [3:0] in_1,
    input [3:0] in_2,
    input [3:0] in_3,
    input [1:0] sel,
    output [3:0] out
); 

    wire [3:0] SHIFTED_DATA;
    wire [3:0] MUX_OUT;
    wire [3:0] FINAL_OUTPUT;

    barrel_shifter bs_inst(
        .CLK(CLK),
        .SHIFT(SHIFT),
        .DATA(in_0),
        .Q(SHIFTED_DATA)
    );

    mux_4to1 mux_inst(
        .in_0(in_0),
        .in_1(in_1),
        .in_2(in_2),
        .in_3(in_3),
        .sel(sel),
        .out(MUX_OUT)
    );

    or_functional_module or_inst(
        .INPUT_1(SHIFTED_DATA),
        .INPUT_2(MUX_OUT),
        .OUTPUT(FINAL_OUTPUT)
    );

    assign out = FINAL_OUTPUT;

endmodule
module barrel_shifter (
    input CLK,
    input SHIFT,
    input [3:0] DATA,
    output [3:0] Q
);
    reg [3:0] q;
    assign Q = q;
    always @(posedge CLK) begin
        if (!SHIFT) begin
            q <= DATA;
        end else begin
            q <= {DATA, 4'b0000};
        end
    end

endmodule
module mux_4to1 (
    input [3:0] in_0,
    input [3:0] in_1,
    input [3:0] in_2,
    input [3:0] in_3,
    input [1:0] sel,
    output [3:0] out
);
    reg [3:0] mux_out;
    assign out = mux_out;
    always @(*) begin
        case (sel)
            2'b00: mux_out = in_0;
            2'b01: mux_out = in_1;
            2'b10: mux_out = in_2;
            2'b11: mux_out = in_3;
        endcase
    end

endmodule
module or_functional_module (
    input [3:0] INPUT_1,
    input [3:0] INPUT_2,
    output [3:0] OUTPUT
);
    assign OUTPUT = INPUT_1 | INPUT_2;

endmodule
```

