module counter_load_out(
  clk, rst, clk_ena,
  load,
  dfload,
  carry,
  dout
);
  parameter MOD_COUNT = 7;
  parameter WIDTH = 8;
  input clk, rst, clk_ena;
  input load;
  input[WIDTH-1:0] dfload;
  output carry;
  reg carry_tmp;
  assign carry = carry_tmp;
  reg [WIDTH-1:0] count;
  output [WIDTH-1:0] dout;

