    if(rst)
      count <= 0;
    else if(clk_ena)
      if(load)
        count <= dfload;
      else if(count == MOD_COUNT-1)
        count <= 0;
      else
        count <= count+1;
  end

  always @(count) begin
    if(count == MOD_COUNT-1)
      carry_tmp = 'b1;
    else 
      carry_tmp = 'b0;
  end

  assign dout = count;
endmodule
